INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('07eb0890-cad8-4143-82c2-93996f841bcb', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$111. óra: Projektóra$q$, $q$Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "f2bff986-ff69-4ca9-b1b5-7bef66604dc4", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "aa29c1ee-bd6c-40fe-91ad-6bcf615171e7", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "8e114948-09f1-40cc-9325-e68e62e559c1", "text": "A tető színét", "isCorrect": false}, {"id": "134afe27-854b-457a-a9c9-952b997e614e", "text": "Az épület magasságát", "isCorrect": false}, {"id": "f317c796-34be-492d-bb68-adc259134c59", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "76ee4783-b30d-4fdf-86f5-1783eb0e56f1", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "6647fcb2-fe4d-41e6-9a16-2594d58bf13d", "text": "Igaz", "isCorrect": true}, {"id": "b4bc8ef5-9608-41ed-8fdd-0ace83006aab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c66bda22-7a43-4eef-98ba-3c202abf679a", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6383360a-91da-4ec3-b34e-9b8fc18741e0", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "28b342fc-3db7-4feb-a1df-cfa928a3de67", "text": "Igaz", "isCorrect": true}, {"id": "81a1950d-b383-4d4c-b42f-d63b71194471", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7d56c5e2-5402-4633-98d4-8e4af3a85fc9", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "a569d936-b13e-47a9-94e2-f5e514f99a9d", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "0ecafcef-8eee-4454-bc92-5530fd65b83a", "text": "Igaz", "isCorrect": true}, {"id": "fd524501-c08e-4bd2-819d-6805df6e1f26", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2f9847ba-9d40-41ae-b43f-5f153855fc3b", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('735d3b54-b6e2-4ba8-8ca0-84fd583accdc', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$112. óra: Projektóra II.$q$, $q$Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "a5d742ce-a424-4578-ba52-cc0c35fa166a", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "8a04be9a-1da0-4ba7-b50a-bf51863e174a", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "4fbacdd1-2bf2-46e4-b8dd-0264230f6ec7", "text": "Igaz", "isCorrect": true}, {"id": "f3130781-b405-49d8-9c22-2c17c0156832", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "71381045-56ef-4629-8e17-b8ae819142d7", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "f3e25f7a-a7f0-4a20-bc38-fff46f8bd78b", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "a6691388-d549-4050-b2c6-1fd8f6f1bd4e", "text": "Gömbökből", "isCorrect": false}, {"id": "45697fc9-71df-4948-a3cc-73920cec875d", "text": "Kúpokból", "isCorrect": false}, {"id": "f54d56bb-3cf1-4d21-80af-335c85e7dd31", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "897574f5-6225-451c-8c8c-78519d8a8808", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "1fb652d2-ab9c-458d-82f8-d68d249f9700", "text": "Igaz", "isCorrect": true}, {"id": "839cfbae-e41f-45a4-a521-5a6e702a2774", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9ba8988-8275-4bfb-804e-f74daf4bdd27", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "93b1c234-e725-4b12-add4-44d5a6aeffdd", "text": "A projektmunka kreatív megoldásokat ösztönöz.", "type": "true-false", "options": [{"id": "fd1f3d16-cc04-4cff-889c-3541f9d17644", "text": "Igaz", "isCorrect": true}, {"id": "02afe27e-952a-43db-81c2-cdcc113932d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7db447fa-ce41-4632-ab9c-c063915519b1", "text": "Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e994977f-2e00-49a1-b6e9-562ad3f6b723', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$113. óra: Projektóra III.$q$, $q$Az elkészített projektek és makettek bemutatása, csoportértékelés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "f180bae6-ce8e-44db-83ce-c86c36ed70e1", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "0ef8fe63-5ca9-4380-999f-e91744c32f4e", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "d131baca-befe-4282-8325-2badab8efd12", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "795238f2-a94d-459c-8885-6d10e3fae605", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "227efa59-deab-444c-94b2-24e2b3d02c06", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "9ef8de15-f2b3-4912-b88f-11f33134b25b", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "4937880e-6ea5-43a4-a663-63dac020d1b7", "text": "Igaz", "isCorrect": true}, {"id": "7c53b14a-78ff-445f-b591-1fc597412fd4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "791dc9d1-ddd6-488f-b6a0-7a5a0ebde084", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "44bcfc78-4b91-41c9-8ee5-2f3b78c189c2", "text": "Igaz", "isCorrect": true}, {"id": "d98e8ace-7498-4833-9957-8433c1d60331", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8a3830d2-05a6-431f-a67c-82520388d2d1", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "190703e6-d4d2-4d9d-8d77-18e7be8812c5", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "42e67c2a-e55d-46f8-9246-3a3cbfa50438", "text": "Igaz", "isCorrect": true}, {"id": "d1327f0f-bb1a-4185-920f-226d0d30e974", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e9449df8-7db3-46d6-bfd1-c0adece1f313", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "96db82ae-e088-47ad-a7c0-3560bef3dfaa", "text": "Igaz", "isCorrect": true}, {"id": "4862ba35-d7f4-4f7b-b4df-e41c7c7b42b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ce4b2f67-c2a9-424e-acaf-71fb9382a0c0", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7d563bc4-7d99-4854-8da9-241e42296767', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$114. óra: Összefoglalás$q$, $q$A Kerület, terület, felszín és térfogat fejezet összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "e088f199-d590-4e67-9e39-d9cb5c9acdef", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "935929d5-857e-46eb-a6d0-697035fb42c6", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "1ea4fbeb-bc04-4a27-bcb7-caa0e0aee6bd", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "3e236459-454e-49bd-ad2c-b4a793a2dbed", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "45e9d00d-56d3-4ece-adfc-fe5533a10491", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "ef376bf4-f11e-459a-9366-2e43fe16b898", "text": "Igaz", "isCorrect": true}, {"id": "0cf4feb0-2822-4a60-ac23-a1d58b9ec856", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bee52e52-38c3-4adf-a046-6ada27239b69", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "97fd277b-d114-4dda-b4f3-ef117fd2aa9f", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "cc4ac8aa-8a61-48c2-94ad-4faa4444e82d", "text": "Igaz", "isCorrect": true}, {"id": "a5197d30-5560-4814-aa26-c2223d2adf79", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('20732148-3512-4f43-a883-b5af497f45a7', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$115. óra: Gyakorlóóra$q$, $q$Gyakorló feladatsor önálló megoldása a mérések témakörben.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "e9f74e78-1dab-45e9-8d11-6f14b8a6f0e9", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "2ad7c7dc-d67e-4ddc-a0f7-2435349a0e89", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "f621e76f-e70a-41a2-b704-d6f112196313", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "a8bad3ed-8987-4b69-a630-4fb66d026b0e", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "f6b2af22-cadf-4254-b196-59b57671a90b", "text": "Igaz", "isCorrect": true}, {"id": "5a620d2e-0d0f-463b-a34e-28febfb69f3d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "32dc3bdd-8458-4015-a181-a2ab2dc82212", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "1fecc5ab-ec01-4739-8fac-a6b73987675d", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "80eb8dba-e337-4801-8141-c55673d7cd8f", "text": "Igaz", "isCorrect": true}, {"id": "65d1e762-dca8-4f9f-be8d-fa2b50b2841d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "95df1d91-f866-4ca2-bf32-5736235a8ddd", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('40fc33c0-a6f7-4e9a-aa6e-c0ab6c627bae', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$116. óra: Feladatmegoldás$q$, $q$Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "e61453fe-7f81-4887-b180-83ba4d8247e0", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "f49d8e99-45eb-408b-972c-bb1d11b122b1", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "d75c7002-00c7-4e89-a862-21c8237c9b20", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "68b49d74-2273-4883-a409-cf56744ec278", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "1df1a8ef-b56d-47b1-8a97-9b4387f07515", "text": "Igaz", "isCorrect": true}, {"id": "76367e31-f788-4248-bde5-10e1bd21cdc6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d649b09c-27b2-443f-ac61-a62c67eb7d1f", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "6c08d379-b84b-4626-8635-cc74493ac1af", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "ac81b63c-7537-4dc0-a517-b675942f2214", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "ff319c94-fcd6-413a-8e76-669d5e0b3f99", "text": "Igaz", "isCorrect": true}, {"id": "80576e7d-e595-48ca-bb78-bd2863f196df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('102401aa-8324-451d-9e21-75b9ec645a29', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$117. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés a Kerület, terület, felszín és térfogat fejezetből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "a4b5de9d-d564-45a8-ae3f-cfe4fdbd4f7f", "text": "1. Mennyi a 6 cm és 9 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "9a9dd742-d5a8-4d9d-bdce-597166e9b51a", "text": "2. Mennyi a 6 cm és 9 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "bdddb85f-9dad-4089-a480-2722aa23a02e", "text": "3. Mennyi a 5 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "5693e3a4-54fe-47d4-99d0-7145fad82ca6", "text": "4. Mennyi a 5 cm élű kocka térfogata? (cm³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "125"}, {"id": "d8779640-eed7-443b-8645-b5a416e5a1ba", "text": "5. Mennyi a 3 cm, 4 cm, 6 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}, {"id": "a99ca9c5-b606-4056-a888-9286b081ceb1", "text": "6. Hány cm² 4 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "a25a861c-6d47-4de0-9d12-706b056c8403", "text": "7. Hány dm³ 3 m³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "037c09bf-7de0-49a1-bb4b-0b79bbe22c01", "text": "8. Hány liter víz fér el 5 dm³-es edényben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "2e9be657-e711-4171-b5e7-ebbe11faca60", "text": "9. A derékszögű háromszög területe a befogók szorzatának fele.", "type": "true-false", "options": [{"id": "07ff53f7-aaee-4fa0-b352-c51bc09b11c1", "text": "Igaz", "isCorrect": true}, {"id": "8869ef32-de94-4dab-9afa-f96a8f0d362c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "42871253-44c5-4794-9d2f-de6d0413710b", "text": "10. Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('79a3ad0d-6f00-43c5-be96-8b98bec10300', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$118. óra: Témazáró dolgozat értékelése$q$, $q$A témazáró dolgozat megbeszélése és a mérések összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "803d2b41-9cee-4e87-a1af-47bd6fe983e6", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "64ce5aa6-07c1-47e0-bc76-7f6d83b5d346", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "054ec5b7-e38b-44a4-8cae-72f05cce2a28", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "6dc5a99d-6e17-4c27-aab6-35de637c306c", "text": "A számláló írása", "isCorrect": false}, {"id": "f4f17b67-c791-43a5-8a58-311fe36fecd8", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "0b222fff-fd64-4aa1-8078-d01063b5e0f9", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "0ba96a2a-4728-41ff-b0b0-7fe26d16d9b2", "text": "Igaz", "isCorrect": true}, {"id": "f4b9ec2a-e5c3-4785-b2df-3654f9dba7a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4364811-d4b3-45aa-bc84-55360a8a1404", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "b36f602a-f0ca-4d8c-afed-a29cd042cdb0", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "cb5be4dc-8fda-497a-8445-98218e69a517", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "f1bb74bb-96d0-479b-a211-c7296f1bf902", "text": "Igaz", "isCorrect": true}, {"id": "794f5038-f3a6-450e-af36-b91fea30c03d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bd880948-f580-41ff-9bb8-6bc28ae4245c", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "7793cd1e-189f-4723-92d1-798ecb012844", "text": "A hibajavítás segít a pontosabb tudás megszilárdításában.", "type": "true-false", "options": [{"id": "f1bcbeb4-8551-41a0-8ccb-dad72a79aabb", "text": "Igaz", "isCorrect": true}, {"id": "46c9156a-035d-4db6-9dd5-5e46fa762c2f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4e085db4-f900-4215-995f-f729858d8cbe', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$119. óra: Játék$q$, $q$Adatgyűjtési kifejezések, játékszabályok értelmezése, megfigyelés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "250e0546-406a-433d-b1e6-768af9c9af53", "text": "Mi a statisztika fő célja?", "type": "multiple-choice", "options": [{"id": "787635b8-f0c7-432f-868c-65f0888b6845", "text": "Adatok gyűjtése, rendszerezése, ábrázolása és elemzése a döntéshozatalhoz", "isCorrect": true}, {"id": "a882e072-2431-46f9-8f36-afd7bc41264f", "text": "Színes rajzok készítése", "isCorrect": false}, {"id": "ece0d060-f097-4955-ba1d-eb09208b0518", "text": "Számok törlése", "isCorrect": false}, {"id": "655cf852-a73f-4972-b1d4-a6165fb38056", "text": "Csak a legnagyobb szám megtalálása", "isCorrect": false}], "timeLimit": 15}, {"id": "b848186b-8779-401b-b588-bb7c652c6bfe", "text": "Az adatok gyűjtése történhet megfigyeléssel, méréssel vagy kérdőívvel.", "type": "true-false", "options": [{"id": "ac2f085d-2565-4937-97a9-02e3a9b1ae51", "text": "Igaz", "isCorrect": true}, {"id": "5b7d0914-08a1-4756-95f4-f9deef7b1dc1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7188a722-56ab-40d4-b176-2ea4bde9f2d0", "text": "Melyik nem statisztikai adatgyűjtési módszer?", "type": "multiple-choice", "options": [{"id": "25d64952-1a41-4768-b83c-618aaca94dd8", "text": "Alvás", "isCorrect": true}, {"id": "2110eb00-00e5-4afe-bc2a-2577b8f22138", "text": "Kérdőíves felmérés", "isCorrect": false}, {"id": "e89351ec-eb46-4afd-bb8a-6bff35f256df", "text": "Hőmérséklet-mérés", "isCorrect": false}, {"id": "ce7093fe-0fea-4198-9c9f-25ea6c234f93", "text": "Szavazás", "isCorrect": false}], "timeLimit": 15}, {"id": "bd9bc86f-d6b4-4276-828d-6b46ed7b8a06", "text": "A gyűjtött adatokat áttekinthető módon táblázatba foglalhatjuk.", "type": "true-false", "options": [{"id": "9b52e001-d31a-484a-a93c-836f955e77ae", "text": "Igaz", "isCorrect": true}, {"id": "868d32fc-d065-4354-82a3-a5421606a2cd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4c598d15-d886-4656-8a18-1f603d1b8506", "text": "Hány válaszlehetőség van egy 'igen/nem' típusú kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "a60d26b6-40dd-45bc-bf36-da7e0f312786", "text": "A statisztikai mintavétel során a cél a pontos és torzításmentes adatszerzés.", "type": "true-false", "options": [{"id": "4588ef27-2bb9-4caf-afb5-1a513912ab3e", "text": "Igaz", "isCorrect": true}, {"id": "a3031fb9-4e0e-4b3c-8cf5-ff08e1570dbc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "13e7f87b-c406-42bc-bdc0-6c14f40b80ed", "text": "Az adatok rendszerezése megkönnyíti a döntéshozatalt.", "type": "true-false", "options": [{"id": "fb1b4f57-fbd1-48f6-afb0-16d98eef4489", "text": "Igaz", "isCorrect": true}, {"id": "51e17ec1-8036-48f1-a44a-70c6f2055e38", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b1b769b9-8391-4fff-bb06-4ecd252308e0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$120. óra: Grafikonok, diagramok, összefüggések$q$, $q$Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "0f4856d0-737b-4418-8958-fd51e442b9f8", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "e7cb93af-129a-46cc-b2cd-72ef70f87789", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "17815557-f970-44cb-b075-26646b289cca", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "f7833f7a-9d9d-4481-ab69-eaa3ee997d22", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "2d3b788d-5b42-4644-81a0-ae18879d3919", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "4de7b3ba-676d-4bf5-812d-1fef3b108614", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "0c8bee8f-e5cf-4f94-b63e-38d7fbca0dc2", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "d77eac76-0f04-4970-b481-2e65b686a2a2", "text": "Számok összeadására", "isCorrect": false}, {"id": "8d41e1e4-dd15-4c8d-9c98-eaad936f44b2", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "56623061-9653-444f-8702-0f70706fae68", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "baccd69d-4392-4910-92c7-8ebf8314f1a3", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "8a0ee0fa-ea70-4444-a50e-595a09cb1fe0", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "72737b28-d9bb-4ff2-8ffb-8a4d8c2d2f29", "text": "Igaz", "isCorrect": true}, {"id": "18c4f47b-9a07-406f-898f-eae0cd3084bd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5b2f990d-7ed1-464e-8bbf-adad39d28b7b", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "5ac6a8f1-a63f-4ccd-9346-538023b0ee0e", "text": "Igaz", "isCorrect": true}, {"id": "5878538a-185d-41f0-bf57-3bd5fc3bc9e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d970898c-6a6f-46fc-b9f0-03fbc2bcde5d", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "b0619088-0644-457e-9e24-d8b63ac1ceb9", "text": "Igaz", "isCorrect": true}, {"id": "0f247cc9-c030-4d87-b371-437745fa9b81", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2bd09b38-00bd-4cbd-a0e0-8f38b3b3e5a9", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;